Here's a complete implementation:

```csharp
// In Program.cs

// Configure max request body size (before builder.Build())
builder.Services.Configure<Microsoft.AspNetCore.Http.Features.FormOptions>(options =>
{
    options.MultipartBodyLengthLimit = 10 * 1024 * 1024; // 10 MB
});

// If using Kestrel directly:
builder.WebHost.ConfigureKestrel(options =>
{
    options.Limits.MaxRequestBodySize = 10 * 1024 * 1024;
});

var app = builder.Build();

// Ensure uploads directory exists
Directory.CreateDirectory(Path.Combine(app.Environment.ContentRootPath, "uploads"));

app.UseAntiforgery();

app.MapPost("/upload", async (IFormFile file, IWebHostEnvironment env) =>
{
    // Validate content type
    string[] allowedTypes = ["image/jpeg", "image/png"];
    if (!allowedTypes.Contains(file.ContentType))
    {
        return Results.BadRequest("Only JPEG and PNG files are allowed.");
    }

    // Validate size
    if (file.Length > 10 * 1024 * 1024)
    {
        return Results.BadRequest("File size must not exceed 10 MB.");
    }

    // Generate safe filename
    var extension = Path.GetExtension(file.FileName).ToLowerInvariant();
    if (extension is not ".jpg" and not ".jpeg" and not ".png")
    {
        return Results.BadRequest("Invalid file extension.");
    }

    var fileName = $"{Guid.NewGuid()}{extension}";
    var filePath = Path.Combine(env.ContentRootPath, "uploads", fileName);

    await using var stream = new FileStream(filePath, FileMode.Create);
    await file.CopyToAsync(stream);

    return Results.Ok(new { fileName, size = file.Length });
})
.DisableAntiforgery(); // Remove this line if you want antiforgery enforced on this endpoint
```

Key points:

- **Size limit** is enforced at both Kestrel and form-options level, plus an explicit check in the handler.
- **Content type + extension** are both validated to prevent spoofing.
- **Safe filename** uses a GUID to avoid path traversal or collisions.
- **`.DisableAntiforgery()`** — since your pipeline has `UseAntiforgery()`, multipart POST requests will require an antiforgery token by default. Remove `.DisableAntiforgery()` if clients will supply the token; keep it for API clients that won't.
